#!/usr/bin/env python3
# /// script
# name: build-asset-gallery
# purpose: 素材台帳からオフライン素材一覧HTMLを生成し、--checkで再生成結果を照合する
# inputs: argv: --check、assets/catalog.json
# outputs: assets/index.html または一致/不一致の終了コード
# contexts: [C, E]
# network: false
# write-scope: --checkはnone。生成時はassets/index.htmlのみ
# dependencies: []
# ///
"""Derive the existing offline asset gallery from catalog.json (stdlib only)."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEMPLATE = '<!-- Generated by scripts/build-asset-gallery.py; edit assets/catalog.json, not this file. -->\n<!doctype html><html lang="ja"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flyer Studio 素材を選ぶ</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f7f7f3;color:#19322d;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Hiragino Kaku Gothic ProN","Noto Sans JP",sans-serif}header,main,footer{max-width:1280px;margin:auto;padding:32px 28px}header{padding-bottom:8px}h1{font-size:30px;letter-spacing:.02em;margin:0 0 12px}p{max-width:90ch}.notice{border-left:4px solid #168779;padding:4px 16px;background:#eef4ef}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}button{font:inherit;border:1px solid #baccc4;background:#fff;color:#19322d;padding:8px 16px;cursor:pointer}button[aria-pressed=true]{background:#19322d;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:24px}article{background:#fff;padding:16px;min-width:0;box-shadow:0 2px 10px #19322d0a}.visual{background:#eef1ed;aspect-ratio:4/3;position:relative;overflow:hidden}.visual img,.visual svg{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:contain;overflow:hidden}.visual.logo{background:#fff}.visual.crop svg{max-height:100%}h2{font-size:18px;margin:13px 0 5px}small{font-size:12px;display:block;color:#47635a}.badge{display:inline-block;font-size:12px;background:#edf5ed;padding:2px 7px;margin:6px 0}.badge.ref{background:#f3ede4;color:#705126}.badge.recommended{background:#0e6658;color:#fff}.badge.preset{background:#e7ecf6;color:#2c4470;margin-left:6px}.notes{font-size:13px;line-height:1.65;min-height:5em}a{color:#166b66;text-underline-offset:3px}.path{font-family:monospace;font-size:12px;overflow-wrap:anywhere}footer{font-size:13px;border-top:1px solid #dbe4dd}#summary{font-size:14px}.filelink{font-size:13px}button:focus-visible,a:focus-visible{outline:3px solid #12a0b2;outline-offset:3px}@media(prefers-reduced-motion:no-preference){button{transition:background .15s}}\n</style><header><h1>Flyer Studio 素材を選ぶ</h1><p>写真・ロゴ・参考の候補を見て、使うIDを制作担当へ伝えてください。新しい画像の追加・差替えも可能です。</p><div class="notice" id="policies"></div><label>案件素材 <select id="preset-scope"><option value="">汎用のみ</option></select></label><nav class="controls" aria-label="素材の種類"></nav><p id="summary" aria-live="polite"></p></header><main><div class="grid" id="gallery"></div></main><footer>必須クロップ（requiredCropPx）のある素材は、その範囲だけを表示しています。原画像リンク先は掲載用の構図ではありません。各素材の公開範囲・加工条件は catalog.json を参照してください。過去チラシの日時・金額・QRは、新案件へ流用できません。<p><a href="catalog.json">素材カタログ JSON</a></p></footer><script type="application/json" id="catalog">@@CATALOG_JSON@@</script><script>\nconst catalog=JSON.parse(document.getElementById(\'catalog\').textContent);const labels={all:\'すべて\',photo:\'写真\',logo:\'ロゴ\',example:\'完成例\',reference:\'参考\',background:\'過去背景\'};let counts={};const summaryKinds=[\'photo\',\'logo\',\'reference\',\'example\',\'background\'];const summaryNames={background:\'背景\'};const countOf=kind=>counts[kind]||0;\nconst notice=document.getElementById(\'policies\');for(const text of Object.values(catalog.policies||{})){const p=document.createElement(\'p\');p.textContent=text;notice.append(p)}notice.hidden=!notice.children.length;const presetScope=document.getElementById(\'preset-scope\');for(const id of [...new Set(catalog.entries.map(e=>e.preset).filter(Boolean))].sort()){const option=document.createElement(\'option\');option.value=id;option.textContent=id+\' の案件\';presetScope.append(option)}presetScope.onchange=()=>render([...nav.children].find(b=>b.getAttribute(\'aria-pressed\')===\'true\')?.dataset.kind||\'all\');\nconst nav=document.querySelector(\'nav\');for(const[key,label]of Object.entries(labels)){const b=document.createElement(\'button\');b.textContent=key===\'all\'?label:label+\' \'+countOf(key)+(key===\'logo\'?\'形式\':\'\');b.dataset.kind=key;b.setAttribute(\'aria-pressed\',key===\'all\');b.onclick=()=>{for(const n of nav.children)n.setAttribute(\'aria-pressed\',n===b);render(key)};nav.append(b)}\nfunction render(kind){const visible=catalog.entries.filter(e=>!e.preset||e.preset===presetScope.value);counts=visible.reduce((r,e)=>{r[e.kind]=(r[e.kind]||0)+1;return r},{});for(const b of nav.children){const key=b.dataset.kind;b.textContent=key===\'all\'?labels[key]:labels[key]+\' \'+countOf(key)+(key===\'logo\'?\'形式\':\'\')}const items=visible.filter(e=>kind===\'all\'||e.kind===kind);document.getElementById(\'summary\').textContent=items.length+\' 点を表示（\'+summaryKinds.map(key=>(summaryNames[key]||labels[key])+\' \'+countOf(key)).join(\'・\')+\'）\';const g=document.getElementById(\'gallery\');g.replaceChildren();for(const e of items){const card=document.createElement(\'article\');card.dataset.id=e.id;const v=document.createElement(\'div\');v.className=\'visual \'+(e.kind===\'logo\'?\'logo\':\'\');if(e.requiredCropPx){v.classList.add(\'crop\');const[x,y,w,h]=e.requiredCropPx;const ns=\'http://www.w3.org/2000/svg\';const svg=document.createElementNS(ns,\'svg\');svg.setAttribute(\'viewBox\',[x,y,w,h].join(\' \'));svg.setAttribute(\'preserveAspectRatio\',\'xMidYMid slice\');svg.setAttribute(\'role\',\'img\');svg.setAttribute(\'aria-label\',e.label+\'（必須クロップ済み表示）\');const im=document.createElementNS(ns,\'image\');im.setAttribute(\'href\',e.file);im.setAttribute(\'width\',e.dimensionsPx[0]);im.setAttribute(\'height\',e.dimensionsPx[1]);svg.append(im);v.append(svg)}else{const im=document.createElement(\'img\');im.src=e.file;im.alt=e.label;im.loading=\'lazy\';v.append(im)}const title=document.createElement(\'h2\');title.textContent=e.id+\' \'+e.label+(e.aliases?.length?\'（別名 \'+e.aliases.join(\'・\')+\'）\':\'\');const badge=document.createElement(\'span\');badge.className=\'badge \'+(e.recommendedAxisReference?\'recommended\':e.usage===\'reference-only\'?\'ref\':\'\');badge.textContent=e.recommendedAxisReference?\'推奨：紙面の中央軸\':e.usage===\'reference-only\'?\'構成の参考のみ\':e.kind===\'background\'?\'明示選択時だけ再利用\':\'毎回選択を確認\';const scope=document.createElement(\'span\');if(e.preset){scope.className=\'badge preset\';scope.textContent=\'preset専用: \'+e.preset}const p=document.createElement(\'p\');p.className=\'notes\';p.textContent=e.notes;const file=document.createElement(\'p\');file.className=\'path\';file.textContent=e.file;const link=document.createElement(\'a\');link.href=e.file;link.className=\'filelink\';link.textContent=e.requiredCropPx?\'原画像を見る（そのまま掲載不可）\':\'画像を見る\';link.target=\'_blank\';link.rel=\'noopener\';card.append(v,title,badge,scope,p,file,link);g.append(card)}}render(\'all\');\n</script></html>'

def build(catalog=None):
    if catalog is None:
        catalog = json.loads((ROOT / "assets/catalog.json").read_text(encoding="utf-8"))
    # Keep embedded JSON safe even when notes contain HTML/script-like text.
    data = json.dumps(catalog, ensure_ascii=False).replace("<", "\\u003c")
    return TEMPLATE.replace("@@CATALOG_JSON@@", data)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail on drift without writing")
    args = parser.parse_args()
    target = ROOT / "assets/index.html"
    expected = build()
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != expected:
            parser.exit(1, "asset gallery drift: run python3 scripts/build-asset-gallery.py\n")
        print("asset gallery matches catalog.json")
    else:
        target.write_text(expected, encoding="utf-8")
        print(target)

if __name__ == "__main__":
    main()
